#include "lua_mse_snapshot.h"
#include "project_encode.h"
#include "free_tile_project_json.h"
#include <codecvt>
#include <locale>
// Existing project serializer shared without exposing WinRT headers to every
// editor translation unit through the lightweight project_encode interface.
namespace moon::project {void writeColorOverlay(winrt::Windows::Data::Json::JsonObject&,const std::optional<timeline::ColorOverlayStyle>&);}
namespace moon::script {
namespace {
using namespace winrt::Windows::Data::Json;
constexpr std::size_t resourceLimit=1048576;
std::string utf8(const std::u32string& s){return std::wstring_convert<std::codecvt_utf8<char32_t>,char32_t>{}.to_bytes(s);}
void text(JsonObject o,const wchar_t* k,const std::string& s){o.Insert(k,JsonValue::CreateStringValue(winrt::to_hstring(s)));}
void number(JsonObject o,const wchar_t* k,double n){o.Insert(k,JsonValue::CreateNumberValue(n));}
void flag(JsonObject o,const wchar_t* k,bool b){o.Insert(k,JsonValue::CreateBooleanValue(b));}
JsonObject color(Pixel p){JsonObject o;int shift=0;for(auto key:{L"r",L"g",L"b",L"a"}){number(o,key,(p>>shift)&255);shift+=8;}return o;}
template<class T>JsonArray numbers(const T& values){JsonArray out;for(auto value:values)out.Append(JsonValue::CreateNumberValue(value));return out;}
template<class T>JsonArray strings(const T& values){JsonArray out;for(const auto& value:values)out.Append(JsonValue::CreateStringValue(winrt::to_hstring(value)));return out;}
JsonObject layerInfo(const Document& d,const timeline::Layer& l){
 JsonObject o;const auto g=d.displayedLayerGeometry(l.id);text(o,L"id",l.id);text(o,L"name",utf8(l.name));text(o,L"kind",l.kind.empty()?"raster":l.kind);o.Insert(L"groupId",l.groupId?JsonValue::CreateStringValue(winrt::to_hstring(*l.groupId)):JsonValue::CreateNullValue());
 number(o,L"width",g[0]);number(o,L"height",g[1]);number(o,L"x",g[2]);number(o,L"y",g[3]);number(o,L"opacity",std::floor(l.opacity*255+.5));flag(o,L"visible",l.visible);flag(o,L"locked",l.locked);text(o,L"format","rgba");text(o,L"blendMode",l.blendMode);o.Insert(L"displayColor",l.displayColor?color(*l.displayColor).as<IJsonValue>():JsonValue::CreateNullValue());text(o,L"description",utf8(l.description));
 JsonObject style;project::writeColorOverlay(style,l.layerStyles);o.Insert(L"styles",style.HasKey(L"layerStyles")?style.GetNamedValue(L"layerStyles"):JsonValue::CreateNullValue());o.Insert(L"tilemapTilesetId",l.tilemapTilesetId.empty()?JsonValue::CreateNullValue():JsonValue::CreateStringValue(winrt::to_hstring(l.tilemapTilesetId)));o.Insert(L"freeTileSetId",l.freeTiles?JsonValue::CreateStringValue(winrt::to_hstring(l.freeTiles->setId)):JsonValue::CreateNullValue());return o;
}
}
std::string buildMseSnapshot(const Document& d,const std::vector<StoredPatternBrush>& local,const JsonArray& panels){
 JsonObject out,doc,animation,range,palette,tiles,free,workspace;const auto& state=d.timeline().state();const auto& active=d.layer();
 text(doc,L"id",d.projectId());text(doc,L"name",utf8(d.name()));text(doc,L"filePath",winrt::to_string(d.sourceFilePath().wstring()));number(doc,L"width",d.width());number(doc,L"height",d.height());text(doc,L"colorMode",std::string(color_mode::name(d.colorMode())));const auto frame=std::find_if(state.frames.begin(),state.frames.end(),[&](const auto& f){return f.id==d.frame().id;});number(doc,L"frame",std::max<std::ptrdiff_t>(0,frame-state.frames.begin())+1);doc.Insert(L"activeLayer",layerInfo(d,active));out.Insert(L"document",doc);
 // Legacy document.layers is bottom-to-top; native model is top-to-bottom.
 JsonArray layers;for(auto it=state.layers.rbegin();it!=state.layers.rend();++it)layers.Append(layerInfo(d,*it));out.Insert(L"layers",layers);
 JsonArray frames,loops;for(std::size_t i=0;i<state.frames.size();++i){const auto& f=state.frames[i];JsonObject o;text(o,L"id",f.id);number(o,L"number",i+1);number(o,L"duration",f.duration);flag(o,L"disabled",f.disabled);flag(o,L"active",f.id==d.frame().id);frames.Append(o);}for(const auto& l:state.loopSections){JsonObject o;text(o,L"id",l.id);text(o,L"name",utf8(l.name));text(o,L"startFrameId",l.startFrameId);text(o,L"endFrameId",l.endFrameId);text(o,L"direction",l.direction);if(l.repeatCount)number(o,L"repeatCount",*l.repeatCount);loops.Append(o);}animation.Insert(L"frames",frames);animation.Insert(L"loops",loops);out.Insert(L"animation",animation);
 auto layerIds=d.selectedDirectLayerIds(),frameIds=d.selectedFrames();if(layerIds.empty())layerIds.push_back(active.id);if(frameIds.empty())frameIds.push_back(d.frame().id);range.Insert(L"layerIds",strings(layerIds));range.Insert(L"frameIds",strings(frameIds));std::vector<std::string> cellKeys;for(const auto& id:d.timelineSelection().cels)if(const auto* c=d.timeline().findCelById(id))cellKeys.push_back(c->layerId+":"+c->frameId);range.Insert(L"cellKeys",strings(cellKeys));out.Insert(L"range",range);
 const auto& p=d.palette();JsonArray entries;for(const auto& e:p.entries){JsonObject o;number(o,L"id",e.id);text(o,L"name",utf8(e.name));o.Insert(L"color",color(e.color));entries.Append(o);}palette.Insert(L"entries",entries);palette.Insert(L"order",numbers(p.order()));JsonArray slots;for(int id:p.slots)slots.Append(id==EmptyPaletteSlot?JsonValue::CreateNullValue():JsonValue::CreateNumberValue(id));palette.Insert(L"slots",slots);number(palette,L"columns",p.columns);number(palette,L"nextColorId",p.nextId);out.Insert(L"palette",palette);
 std::size_t used=0;JsonArray sets;for(const auto& t:state.tilesets){JsonObject o;text(o,L"id",t.id);text(o,L"name",utf8(t.name));number(o,L"tileWidth",t.tileWidth);number(o,L"tileHeight",t.tileHeight);number(o,L"columns",t.columns);number(o,L"rows",t.rows);o.Insert(L"tileIds",strings(t.tileIds));JsonArray slots;for(const auto& s:t.tileSlots)slots.Append(s?JsonValue::CreateStringValue(winrt::to_hstring(*s)):JsonValue::CreateNullValue());o.Insert(L"tileSlots",slots);if(t.pixels.size()<=resourceLimit-used){used+=t.pixels.size();o.Insert(L"pixels",numbers(t.pixels));}else o.Insert(L"pixels",JsonValue::CreateNullValue());sets.Append(o);}tiles.Insert(L"sets",sets);out.Insert(L"tiles",tiles);
 const bool isFree=active.kind=="free-tile";free.Insert(L"layerId",isFree?JsonValue::CreateStringValue(winrt::to_hstring(active.id)):JsonValue::CreateNullValue());text(free,L"frameId",d.frame().id);free.Insert(L"setId",isFree?JsonValue::CreateStringValue(winrt::to_hstring(active.freeTiles?active.freeTiles->setId:active.id)):JsonValue::CreateNullValue());JsonArray sources,instances;if(isFree&&active.freeTiles){JsonObject encoded;project::freejson::encodeLayer(encoded,*active.freeTiles);sources=encoded.GetNamedArray(L"freeTileSources");for(auto value:sources){auto o=value.GetObject();if(!o.HasKey(L"displayColor"))o.Insert(L"displayColor",JsonValue::CreateNullValue());}if(const auto* cel=d.timeline().findCel(active.id,d.frame().id)){const auto resolved=d.timeline().resolveSurface(cel->id);if(resolved.source&&resolved.source->freeTiles)instances=project::freejson::encodeCel(*resolved.source->freeTiles).GetNamedArray(L"instances");}}free.Insert(L"sources",sources);free.Insert(L"instances",instances);out.Insert(L"freeTiles",free);
 JsonArray brushes;for(const auto& b:d.projectBrushes()){JsonObject o;text(o,L"id",b.metadata.id);text(o,L"name",b.metadata.name);text(o,L"source","project");number(o,L"width",b.brush.width);number(o,L"height",b.brush.height);number(o,L"sourceX",b.metadata.sourceX.value_or(0));number(o,L"sourceY",b.metadata.sourceY.value_or(0));o.Insert(L"coverage",b.brush.coverage.size()<=resourceLimit?numbers(b.brush.coverage).as<IJsonValue>():JsonValue::CreateNullValue());o.Insert(L"colors",!b.brush.colors.empty()&&b.brush.colors.size()<=resourceLimit?numbers(b.brush.colors).as<IJsonValue>():JsonValue::CreateNullValue());brushes.Append(o);}for(const auto& b:local){JsonObject o;text(o,L"id",b.id);text(o,L"name",b.name);text(o,L"source","local");o.Insert(L"folderId",b.folderId.empty()?JsonValue::CreateNullValue():JsonValue::CreateStringValue(winrt::to_hstring(b.folderId)));flag(o,L"intrinsicSize",b.intrinsicSize);number(o,L"sourceX",b.sourceX.value_or(0));number(o,L"sourceY",b.sourceY.value_or(0));brushes.Append(o);}out.Insert(L"brushes",brushes);
 JsonArray slices;for(const auto& s:d.slices()){JsonObject o;text(o,L"id",s.id);text(o,L"name",utf8(s.name));number(o,L"x",s.rect.x);number(o,L"y",s.rect.y);number(o,L"width",s.rect.width);number(o,L"height",s.rect.height);slices.Append(o);}out.Insert(L"slices",slices);workspace.Insert(L"panels",panels);out.Insert(L"workspace",workspace);return winrt::to_string(out.Stringify());
}
}
